11	class Plugin {
12	  Plugin({
13	    required this.name,
14	    required this.path,
15	    required this.platforms,
16	    required this.defaultPackagePlatforms,
17	    required this.pluginDartClassPlatforms,
18	    required this.dependencies,
19	    required this.isDirectDependency,
20	    this.implementsPackage,
21	  }) : assert(name != null),
22	       assert(path != null),
23	       assert(platforms != null),
24	       assert(defaultPackagePlatforms != null),
25	       assert(pluginDartClassPlatforms != null),
26	       assert(dependencies != null),
27	       assert(isDirectDependency != null);
28	
29	  /// Parses [Plugin] specification from the provided pluginYaml.
30	  ///
31	  /// This currently supports two formats. Legacy and Multi-platform.
32	  ///
33	  /// Example of the deprecated Legacy format.
34	  ///
35	  ///     flutter:
36	  ///      plugin:
37	  ///        androidPackage: io.flutter.plugins.sample
38	  ///        iosPrefix: FLT
39	  ///        pluginClass: SamplePlugin
40	  ///
41	  /// Example Multi-platform format.
42	  ///
43	  ///     flutter:
44	  ///      plugin:
45	  ///        platforms:
46	  ///          android:
47	  ///            package: io.flutter.plugins.sample
48	  ///            pluginClass: SamplePlugin
49	  ///          ios:
50	  ///            pluginClass: SamplePlugin
51	  ///          linux:
52	  ///            pluginClass: SamplePlugin
53	  ///          macos:
54	  ///            pluginClass: SamplePlugin
55	  ///          windows:
56	  ///            pluginClass: SamplePlugin
57	  factory Plugin.fromYaml(
58	    String name,
59	    String path,
60	    YamlMap? pluginYaml,
61	    List<String> dependencies, {
62	    required FileSystem fileSystem,
63	    Set<String>? appDependencies,
64	  }) {
65	    final List<String> errors = validatePluginYaml(pluginYaml);
66	    if (errors.isNotEmpty) {
67	      throwToolExit('Invalid plugin specification $name.\n${errors.join('\n')}');
68	    }
69	    if (pluginYaml != null && pluginYaml['platforms'] != null) {
70	      return Plugin._fromMultiPlatformYaml(
71	        name,
72	        path,
73	        pluginYaml,
74	        dependencies,
75	        fileSystem,
76	        appDependencies != null && appDependencies.contains(name),
77	      );
78	    }
79	    return Plugin._fromLegacyYaml(
80	      name,
81	      path,
82	      pluginYaml,
83	      dependencies,
84	      fileSystem,
85	      appDependencies != null && appDependencies.contains(name),
86	    );
87	  }
88	
89	  factory Plugin._fromMultiPlatformYaml(
90	    String name,
91	    String path,
92	    YamlMap pluginYaml,
93	    List<String> dependencies,
94	    FileSystem fileSystem,
95	    bool isDirectDependency,
96	  ) {
97	    assert (pluginYaml['platforms'] != null, 'Invalid multi-platform plugin specification $name.');
98	    final YamlMap platformsYaml = pluginYaml['platforms'] as YamlMap;
99	
100	    assert (_validateMultiPlatformYaml(platformsYaml).isEmpty,
101	            'Invalid multi-platform plugin specification $name.');
102	
103	    final Map<String, PluginPlatform> platforms = <String, PluginPlatform>{};
104	
105	    if (_providesImplementationForPlatform(platformsYaml, AndroidPlugin.kConfigKey)) {
106	      platforms[AndroidPlugin.kConfigKey] = AndroidPlugin.fromYaml(
107	        name,
108	        platformsYaml[AndroidPlugin.kConfigKey] as YamlMap,
109	        path,
110	        fileSystem,
111	      );
112	    }
113	
114	    if (_providesImplementationForPlatform(platformsYaml, IOSPlugin.kConfigKey)) {
115	      platforms[IOSPlugin.kConfigKey] =
116	          IOSPlugin.fromYaml(name, platformsYaml[IOSPlugin.kConfigKey] as YamlMap);
117	    }
118	
119	    if (_providesImplementationForPlatform(platformsYaml, LinuxPlugin.kConfigKey)) {
120	      platforms[LinuxPlugin.kConfigKey] =
121	          LinuxPlugin.fromYaml(name, platformsYaml[LinuxPlugin.kConfigKey] as YamlMap);
122	    }
123	
124	    if (_providesImplementationForPlatform(platformsYaml, MacOSPlugin.kConfigKey)) {
125	      platforms[MacOSPlugin.kConfigKey] =
126	          MacOSPlugin.fromYaml(name, platformsYaml[MacOSPlugin.kConfigKey] as YamlMap);
127	    }
128	
129	    if (_providesImplementationForPlatform(platformsYaml, WebPlugin.kConfigKey)) {
130	      platforms[WebPlugin.kConfigKey] =
131	          WebPlugin.fromYaml(name, platformsYaml[WebPlugin.kConfigKey] as YamlMap);
132	    }
133	
134	    if (_providesImplementationForPlatform(platformsYaml, WindowsPlugin.kConfigKey)) {
135	      platforms[WindowsPlugin.kConfigKey] =
136	          WindowsPlugin.fromYaml(name, platformsYaml[WindowsPlugin.kConfigKey] as YamlMap);
137	    }
138	
139	    // TODO(stuartmorgan): Consider merging web into this common handling; the
140	    // fact that its implementation of Dart-only plugins and default packages
141	    // are separate is legacy.
142	    final List<String> sharedHandlingPlatforms = <String>[
143	      AndroidPlugin.kConfigKey,
144	      IOSPlugin.kConfigKey,
145	      LinuxPlugin.kConfigKey,
146	      MacOSPlugin.kConfigKey,
147	      WindowsPlugin.kConfigKey,
148	    ];
149	    final Map<String, String> defaultPackages = <String, String>{};
150	    final Map<String, String> dartPluginClasses = <String, String>{};
151	    for (final String platform in sharedHandlingPlatforms) {
152	        final String? defaultPackage = _getDefaultPackageForPlatform(platformsYaml, platform);
153	        if (defaultPackage != null) {
154	          defaultPackages[platform] = defaultPackage;
155	        }
156	        final String? dartClass = _getPluginDartClassForPlatform(platformsYaml, platform);
157	        if (dartClass != null) {
158	          dartPluginClasses[platform] = dartClass;
159	        }
160	    }
161	
162	    return Plugin(
163	      name: name,
164	      path: path,
165	      platforms: platforms,
166	      defaultPackagePlatforms: defaultPackages,
167	      pluginDartClassPlatforms: dartPluginClasses,
168	      dependencies: dependencies,
169	      isDirectDependency: isDirectDependency,
170	      implementsPackage: pluginYaml['implements'] != null ? pluginYaml['implements'] as String : '',
171	    );
172	  }
173	
174	  factory Plugin._fromLegacyYaml(
175	    String name,
176	    String path,
177	    dynamic pluginYaml,
178	    List<String> dependencies,
179	    FileSystem fileSystem,
180	    bool isDirectDependency,
181	  ) {
182	    final Map<String, PluginPlatform> platforms = <String, PluginPlatform>{};
183	    final String pluginClass = (pluginYaml as Map<dynamic, dynamic>)['pluginClass'] as String;
184	    if (pluginYaml != null && pluginClass != null) {
185	      final String androidPackage = pluginYaml['androidPackage'] as String;
186	      if (androidPackage != null) {
187	        platforms[AndroidPlugin.kConfigKey] = AndroidPlugin(
188	          name: name,
189	          package: pluginYaml['androidPackage'] as String,
190	          pluginClass: pluginClass,
191	          pluginPath: path,
192	          fileSystem: fileSystem,
193	        );
194	      }
195	
196	      final String iosPrefix = pluginYaml['iosPrefix'] as String? ?? '';
197	      platforms[IOSPlugin.kConfigKey] =
198	          IOSPlugin(
199	            name: name,
200	            classPrefix: iosPrefix,
201	            pluginClass: pluginClass,
202	          );
203	    }
204	    return Plugin(
205	      name: name,
206	      path: path,
207	      platforms: platforms,
208	      defaultPackagePlatforms: <String, String>{},
209	      pluginDartClassPlatforms: <String, String>{},
210	      dependencies: dependencies,
211	      isDirectDependency: isDirectDependency,
212	    );
213	  }
