28	void _renderTemplateToFile(String template, Object? context, File file, TemplateRenderer templateRenderer) {
29	  final String renderedTemplate = templateRenderer
30	    .renderString(template, context);
31	  file.createSync(recursive: true);
32	  file.writeAsStringSync(renderedTemplate);
33	}
