1145	// TODO(stuartmorgan): Expand implementation to apply to all implementations,
1146	// not just Dart-only, per the federated plugin spec.
1147	List<PluginInterfaceResolution> resolvePlatformImplementation(
1148	  List<Plugin> plugins, {
1149	  bool throwOnPluginPubspecError = true,
1150	}) {
1151	  final List<String> platforms = <String>[
1152	    AndroidPlugin.kConfigKey,
1153	    IOSPlugin.kConfigKey,
1154	    LinuxPlugin.kConfigKey,
1155	    MacOSPlugin.kConfigKey,
1156	    WindowsPlugin.kConfigKey,
1157	  ];
1158	  final Map<String, PluginInterfaceResolution> directDependencyResolutions
1159	      = <String, PluginInterfaceResolution>{};
1160	  final Map<String, String> defaultImplementations = <String, String>{};
1161	  bool didFindError = false;
1162	
1163	  for (final Plugin plugin in plugins) {
1164	    for (final String platform in platforms) {
1165	      if (plugin.platforms[platform] == null &&
1166	          plugin.defaultPackagePlatforms[platform] == null) {
1167	        // The plugin doesn't implement this platform.
1168	        continue;
1169	      }
1170	      String? implementsPackage = plugin.implementsPackage;
1171	      if (implementsPackage == null || implementsPackage.isEmpty) {
1172	        final String? defaultImplementation = plugin.defaultPackagePlatforms[platform];
1173	        final bool hasInlineDartImplementation =
1174	          plugin.pluginDartClassPlatforms[platform] != null;
1175	        if (defaultImplementation == null && !hasInlineDartImplementation) {
1176	          if (throwOnPluginPubspecError) {
1177	            globals.printError(
1178	              "Plugin `${plugin.name}` doesn't implement a plugin interface, nor does "
1179	              'it specify an implementation in pubspec.yaml.\n\n'
1180	              'To set an inline implementation, use:\n'
1181	              'flutter:\n'
1182	              '  plugin:\n'
1183	              '    platforms:\n'
1184	              '      $platform:\n'
1185	              '        $kDartPluginClass: <plugin-class>\n'
1186	              '\n'
1187	              'To set a default implementation, use:\n'
1188	              'flutter:\n'
1189	              '  plugin:\n'
1190	              '    platforms:\n'
1191	              '      $platform:\n'
1192	              '        $kDefaultPackage: <plugin-implementation>\n'
1193	              '\n'
1194	              'To implement an interface, use:\n'
1195	              'flutter:\n'
1196	              '  plugin:\n'
1197	              '    implements: <plugin-interface>'
1198	              '\n'
1199	            );
1200	          }
1201	          didFindError = true;
1202	          continue;
1203	        }
1204	        if (defaultImplementation != null) {
1205	          defaultImplementations['$platform/${plugin.name}'] = defaultImplementation;
1206	          continue;
1207	        } else if (platform != 'linux' && platform != 'macos' && platform != 'windows') {
1208	          // An interface package (i.e., one with no 'implements') with an
1209	          // inline implementation is its own default implementation.
1210	          // TODO(stuartmorgan): This should be true on desktop as well, but
1211	          // enabling that would be a breaking change for most existing
1212	          // Dart-only plugins. See https://github.com/flutter/flutter/issues/87862
1213	          implementsPackage = plugin.name;
1214	          defaultImplementations['$platform/${plugin.name}'] = plugin.name;
1215	        }
1216	      }
1217	      if (plugin.pluginDartClassPlatforms[platform] == null ||
1218	          plugin.pluginDartClassPlatforms[platform] == 'none') {
1219	        continue;
1220	      }
1221	      final String resolutionKey = '$platform/$implementsPackage';
1222	      if (directDependencyResolutions.containsKey(resolutionKey)) {
1223	        final PluginInterfaceResolution? currResolution = directDependencyResolutions[resolutionKey];
1224	        if (currResolution != null && currResolution.plugin.isDirectDependency) {
1225	          if (plugin.isDirectDependency) {
1226	            if (throwOnPluginPubspecError) {
1227	              globals.printError(
1228	                'Plugin `${plugin.name}` implements an interface for `$platform`, which was already '
1229	                'implemented by plugin `${currResolution.plugin.name}`.\n'
1230	                'To fix this issue, remove either dependency from pubspec.yaml.'
1231	                '\n\n'
1232	              );
1233	            }
1234	            didFindError = true;
1235	          }
1236	          // Use the plugin implementation added by the user as a direct dependency.
1237	          continue;
1238	        }
1239	      }
1240	      directDependencyResolutions[resolutionKey] = PluginInterfaceResolution(
1241	        plugin: plugin,
1242	        platform: platform,
1243	      );
1244	    }
1245	  }
1246	  if (didFindError && throwOnPluginPubspecError) {
1247	    throwToolExit('Please resolve the errors');
1248	  }
1249	  final List<PluginInterfaceResolution> finalResolution = <PluginInterfaceResolution>[];
