final Version _minimumFlutterVersionForImplicitDesktopDefault = Version(2, 11, 0);

/// Whether [plugin] declares a Flutter SDK constraint recent enough for it to
/// be selected as its own default implementation on desktop platforms.
bool _defaultsToOwnImplementationForDesktop(Plugin plugin) {
  final VersionConstraint? flutterConstraint = plugin.flutterConstraint;
  if (flutterConstraint == null || flutterConstraint is! VersionRange) {
